import json
import csv
import pandas as pd

# --- 1. Read all three sources ---

with open("/data/source_a/users.json") as f:
    raw_a = json.load(f)

with open("/data/source_b/users.csv", newline="") as f:
    raw_b = list(csv.DictReader(f))

raw_c = pd.read_parquet("/data/source_c/users.parquet")

# --- 2. Normalize each source to the unified schema ---

def bool_to_status(val):
    if isinstance(val, bool):
        return "active" if val else "inactive"
    if isinstance(val, str):
        return val.lower()
    return str(val)

def normalize_a(rec):
    return {
        "user_id": int(rec["id"]),
        "name": rec["full_name"],
        "email": rec["email"],
        "created_date": rec["registration_date"],
        "status": rec.get("status", ""),
    }

def normalize_b(rec):
    return {
        "user_id": int(rec["user_id"]),
        "name": rec["name"],
        "email": rec["email_address"],
        "created_date": rec["created_at"],
        "status": bool_to_status(rec.get("is_active", "")),
    }

def normalize_c(row):
    return {
        "user_id": int(row["userId"]),
        "name": row["userName"],
        "email": row["email"],
        "created_date": row["joined"],
        "status": bool_to_status(row["active"]),
    }

records_a = {r["user_id"]: r for r in (normalize_a(rec) for rec in raw_a)}
records_b = {r["user_id"]: r for r in (normalize_b(rec) for rec in raw_b)}
records_c = {r["user_id"]: r for r in (normalize_c(row) for _, row in raw_c.iterrows())}

# --- 3. Collect all user_ids ---

all_ids = set(records_a.keys()) | set(records_b.keys()) | set(records_c.keys())

# --- 4. Merge with conflict tracking ---

FIELDS = ["name", "email", "created_date", "status"]
SOURCE_NAMES = ["source_a", "source_b", "source_c"]
SOURCES = [records_a, records_b, records_c]

merged = []
conflicts = []

for uid in sorted(all_ids):
    row = {"user_id": uid}
    for field in FIELDS:
        # Collect values from each source (None if missing)
        vals = {}
        for sname, src in zip(SOURCE_NAMES, SOURCES):
            if uid in src and field in src[uid]:
                vals[sname] = src[uid][field]

        # Pick value from highest-priority source that has it
        selected = None
        for src in SOURCES:
            if uid in src and field in src[uid]:
                selected = src[uid][field]
                break

        row[field] = selected

        # Detect conflicts: more than one source has a value for this field,
        # and they differ
        if len(vals) > 1:
            unique_vals = set(str(v) for v in vals.values())
            if len(unique_vals) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {k: vals[k] for k in SOURCE_NAMES if k in vals},
                    "selected": selected,
                })

    merged.append(row)

# --- 5. Write outputs ---

df = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
df["user_id"] = df["user_id"].astype(int)
df.to_parquet("/app/merged_users.parquet", index=False)

conflict_report = {
    "total_conflicts": len(conflicts),
    "conflicts": conflicts,
}
with open("/app/conflicts.json", "w") as f:
    json.dump(conflict_report, f, indent=2)

print(f"Merged {len(merged)} users to /app/merged_users.parquet")
print(f"Conflicts: {len(conflicts)} written to /app/conflicts.json")
for c in conflicts:
    print(f"  user_id={c['user_id']} field={c['field']} values={c['values']} selected={c['selected']}")

