    if isinstance(val, bool):
        return "active" if val else "inactive"
    if isinstance(val, str):
        return val.lower()
    return str(val)

def normalize_a(rec):
    return {
        "user_id": int(rec["id"]),
        "name": rec["full_name"],
        "email": rec["email"],
        "created_date": rec["registration_date"],
        "status": rec.get("status", ""),
    }

def normalize_b(rec):
    return {
        "user_id": int(rec["user_id"]),
        "name": rec["name"],
        "email": rec["email_address"],
        "created_date": rec["created_at"],
        "status": bool_to_status(rec.get("is_active", "")),
    }

def normalize_c(row):
    return {
        "user_id": int(row["userId"]),
        "name": row["userName"],
        "email": row["email"],
        "created_date": row["joined"],
        "status": bool_to_status(row["active"]),
    }

records_a = {r["user_id"]: r for r in (normalize_a(rec) for rec in raw_a)}
records_b = {r["user_id"]: r for r in (normalize_b(rec) for rec in raw_b)}
records_c = {r["user_id"]: r for r in (normalize_c(row) for _, row in raw_c.iterrows())}

# --- 3. Collect all user_ids ---

